                  "properties": {
                    "Email": {
                      "description": "Email address",
                      "type": "string",
                      "example": "secretary@example.com"
                    },
                    "Name": {
                      "description": "Optional name",
                      "type": "string",
                      "example": "Secretary"
                    }
                  }
                }
              },
              "Subject": {
                "description": "Subject",
                "type": "string",
                "example": "Mailpit message via the HTTP API"
