              "Tags": {
                "description": "Mailpit tags",
                "type": "array",
                "items": {
                  "type": "string"
                },
                "example": [
                  "Tag 1",
                  "Tag 2"
                ]
              },
              "Text": {
                "description": "Message body (text)",
                "type": "string",
                "example": "Mailpit is awesome!"
