GET /view/{ID}.html

Render message HTML part

Renders just the message's HTML part which can be used for UI integration testing. Attached inline images are modified to link to the API provided they exist. Note that is the message does not contain a HTML part then an 404 error is returned.

The ID can be set to latest to return the latest message.

    {
      "produces": [
        "text/html"
      ],
      "schemes": [
        "http",
        "https"
      ],
      "tags": [
        "testing"
      ],
      "operationId": "GetMessageHTMLParams",
      "parameters": [
        {
          "type": "string",
          "description": "Message database ID or \"latest\"",
          "name": "ID",
          "in": "path",
          "required": true
        },
        {
          "type": "string",
          "x-go-name": "Embed",
          "description": "If this is route is to be embedded in an iframe, set embed to `1` in the URL to add `target=\"_blank\"` and `rel=\"noreferrer noopener\"` to all links.\n\nIn addition, a small script will be added to the end of the document to post (postMessage()) the height of the document back to the parent window for optional iframe height resizing.\n\nNote that this will also *transform* the message into a full HTML document (if it isn't already), so this option is useful for viewing but not programmatic testing.",
          "name": "embed",
          "in": "query"
        }
      ],
      "responses": {
        "200": {
          "$ref": "#/responses/HTMLResponse"
        },
        "400": {
          "$ref": "#/responses/ErrorResponse"
        },
        "404": {
          "$ref": "#/responses/NotFoundResponse"
        }
      }
    }

